-- Synthetic fixtures only: all approvals, prices, inventory and orders roll back.
begin;
set local lock_timeout='5s';set local statement_timeout='45s';
select set_config('request.jwt.claims','{}',true);
do $$declare u uuid:=gen_random_uuid();other_user uuid:=gen_random_uuid();a uuid:=gen_random_uuid();s uuid:=gen_random_uuid();p uuid:=gen_random_uuid();gift uuid:=gen_random_uuid();begin
 insert into auth.users(id,email,email_confirmed_at)select id,'bonus-qa-'||id||'@example.invalid',now()from unnest(array[u,other_user,a,s])id;
 insert into public.staff_roles(user_id,market,role)values(a,'PH','admin');
 insert into public.distributor_profiles(user_id,external_member_id,code,display_name,market,active,verified_at)values(s,'QA-'||s,'Q'||replace(s::text,'-',''),'QA bonus sponsor','PH',true,now());
 insert into public.sponsor_attributions(user_id,distributor_id)values(u,s),(other_user,s);
 insert into public.products(id,slug,name,category,status)values(p,'bonus-qa-'||p,'QA qualifying goods','Nutrition','published'),(gift,'bonus-qa-'||gift,'QA bonus goods','Nutrition','published');
 insert into public.product_offers(product_id,market,currency,retail_minor,regulatory_approved,approval_reference,max_quantity)values(p,'PH','PHP',100,true,'ROLLBACK-QA',24),(gift,'PH','PHP',50,true,'ROLLBACK-QA',24);
 insert into public.inventory(product_id,market,on_hand)values(p,'PH',100),(gift,'PH',100);
 update public.markets set online_sales_approved=true,payments_ready=true,policy_reference='ROLLBACK-QA'where code='PH';
 perform set_config('bonus.user',u::text,true);perform set_config('bonus.other',other_user::text,true);perform set_config('bonus.admin',a::text,true);perform set_config('bonus.product',p::text,true);perform set_config('bonus.gift',gift::text,true);
 perform set_config('bonus.items',jsonb_build_array(jsonb_build_object('productId',p,'quantity',2))::text,true);
 perform set_config('bonus.definition',jsonb_build_object('name','Synthetic bonus campaign','qualifyingProductId',p,'minimumQuantity',1,'bonusProductId',gift,'bonusQuantity',1,'maximumPerOrder',2,'maximumUnits',2,'startsAt',now()-interval '1 day','endsAt',now()+interval '1 day','allowVoucher',false,'returnTerms','Synthetic return terms approved only for rollback testing.','capacityAfterRefund','retain')::text,true);
 perform set_config('bonus.address','{"full_name":"QA Customer","phone":"0000000000","line1":"QA fixture address","city":"Manila","postal_code":"1000","country":"PH"}',true);
 perform set_config('bonus.terms',(select checkout_terms_version from public.markets where code='PH'),true);
end $$;
set local role authenticated;
do $$declare c uuid;q jsonb;plain jsonb;o uuid;draft jsonb;k uuid:=gen_random_uuid();items jsonb:=current_setting('bonus.items')::jsonb;address jsonb:=current_setting('bonus.address')::jsonb;terms text:=current_setting('bonus.terms');begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.user'),'role','authenticated','aal','aal1')::text,true);
 plain:=public.quote_fulfilment_checkout('PH',items,null,'{"method":"delivery"}');
 begin perform public.approve_bonus_campaign('PH',current_setting('bonus.definition')::jsonb,'ROLLBACK-QA');raise exception 'FAIL: customer campaign approval';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.admin'),'role','authenticated','aal','aal1')::text,true);
 begin perform public.approve_bonus_campaign('PH',current_setting('bonus.definition')::jsonb,'ROLLBACK-QA');raise exception 'FAIL: campaign without MFA';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.admin'),'role','authenticated','aal','aal2')::text,true);
 begin perform public.approve_bonus_campaign('PH',current_setting('bonus.definition')::jsonb-'capacityAfterRefund','ROLLBACK-QA');raise exception 'FAIL: missing explicit capacity policy';exception when invalid_parameter_value then null;end;
 c:=public.approve_bonus_campaign('PH',current_setting('bonus.definition')::jsonb,'ROLLBACK-QA');perform set_config('bonus.campaign',c::text,true);
 draft:=public.save_commerce_draft(null,'promotion','PH','QA bonus combination','review',jsonb_build_object('productIds',jsonb_build_array(current_setting('bonus.product')),'discountType','fixed','discountValue',5,'minimumSubtotalMinor',0,'maximumDiscountMinor',null,'voucherCode','QA-BONUS-COMBINATION','startsAt',to_char(now()-interval '1 day','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'endsAt',to_char(now()+interval '1 day','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'audience','all','usageLimit',null),0);
 perform public.approve_commerce_draft((draft->>'id')::uuid,1,null,'ROLLBACK-QA');
 begin perform public.approve_bonus_campaign('SG',current_setting('bonus.definition')::jsonb,'ROLLBACK-QA');raise exception 'FAIL: cross-market bonus approval';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.user'),'role','authenticated','aal','aal1')::text,true);
 begin perform public.quote_fulfilment_checkout('PH',items,'QA-BONUS-COMBINATION','{"method":"delivery"}');raise exception 'FAIL: unapproved voucher/bonus combination';exception when invalid_parameter_value then null;end;
 q:=public.quote_fulfilment_checkout('PH',items,null,'{"method":"delivery"}');perform set_config('bonus.quote',q::text,true);
 if q->>'totalMinor'<>'200' or q->'bonusItems'->0->>'quantity'<>'2' or q->>'quoteHash'=plain->>'quoteHash'then raise exception 'FAIL: bonus quote or payable total';end if;
 begin perform public.create_fulfilment_order('PH',items,address,k,terms,null,plain->>'quoteHash',null,'{"method":"delivery"}');raise exception 'FAIL: stale pre-bonus quote';exception when serialization_failure then null;end;
 begin perform public.create_order('PH',items,address,gen_random_uuid(),terms);raise exception 'FAIL: bonus without reviewed quote';exception when serialization_failure then null;end;
 o:=public.create_fulfilment_order('PH',items,address,k,terms,null,q->>'quoteHash',null,'{"method":"delivery"}');perform set_config('bonus.order',o::text,true);
 if public.create_fulfilment_order('PH',items,address,k,terms,null,q->>'quoteHash',null,'{"method":"delivery"}')<>o then raise exception 'FAIL: duplicate bonus order';end if;
 if(select bonus_items->0->>'quantity'from public.orders where id=o)<>'2'then raise exception 'FAIL: frozen bonus snapshot';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.other'),'role','authenticated','aal','aal1')::text,true);
 if exists(select 1 from public.orders where id=o)then raise exception 'FAIL: bonus order disclosure';end if;
 plain:=public.quote_fulfilment_checkout('PH',items,null,'{"method":"delivery"}');
 if plain?'bonusItems'then raise exception 'FAIL: campaign capacity oversubscribed';end if;
 begin perform public.create_fulfilment_order('PH',items,address,gen_random_uuid(),terms,null,q->>'quoteHash',null,'{"method":"delivery"}');raise exception 'FAIL: stale capacity quote';exception when serialization_failure then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.user'),'role','authenticated','aal','aal1')::text,true);
 perform public.cancel_order(o);
 q:=public.quote_fulfilment_checkout('PH',items,null,'{"method":"delivery"}');
 if q->'bonusItems'->0->>'quantity'<>'2'then raise exception 'FAIL: unpaid cancellation did not release campaign capacity';end if;
 k:=gen_random_uuid();o:=public.create_fulfilment_order('PH',items,address,k,terms,null,q->>'quoteHash',null,'{"method":"delivery"}');perform set_config('bonus.paid_order',o::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.admin'),'role','authenticated','aal','aal2')::text,true);
 perform public.withdraw_bonus_campaign(c,'ROLLBACK-QA-WITHDRAW');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.user'),'role','authenticated','aal','aal1')::text,true);
 if public.create_fulfilment_order('PH',items,address,k,terms,null,q->>'quoteHash',null,'{"method":"delivery"}')<>o then raise exception 'FAIL: retry after campaign withdrawal';end if;
end $$;
reset role;
do $$declare c uuid;q jsonb;d jsonb:=current_setting('bonus.definition')::jsonb;begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.admin'),'role','authenticated','aal','aal2')::text,true);
 c:=public.approve_bonus_campaign('PH',d,'ROLLBACK-NEGATIVE');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.user'),'role','authenticated','aal','aal1')::text,true);
 update public.inventory set on_hand=reserved where product_id=current_setting('bonus.gift')::uuid and market='PH';
 begin perform public.quote_fulfilment_checkout('PH',current_setting('bonus.items')::jsonb,null,'{"method":"delivery"}');raise exception 'FAIL: unavailable bonus stock';exception when check_violation then null;end;
 update public.inventory set on_hand=100 where product_id=current_setting('bonus.gift')::uuid and market='PH';
 update public.product_offers set regulatory_approved=false where product_id=current_setting('bonus.gift')::uuid and market='PH';
 begin perform public.quote_fulfilment_checkout('PH',current_setting('bonus.items')::jsonb,null,'{"method":"delivery"}');raise exception 'FAIL: unregistered bonus product';exception when invalid_parameter_value then null;end;
 update public.product_offers set regulatory_approved=true where product_id=current_setting('bonus.gift')::uuid and market='PH';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.admin'),'role','authenticated','aal','aal2')::text,true);
 perform public.withdraw_bonus_campaign(c,'ROLLBACK-NEGATIVE');
 c:=public.approve_bonus_campaign('PH',d||jsonb_build_object('bonusProductId',current_setting('bonus.product')),'ROLLBACK-COMBINED');
 update public.product_offers set max_quantity=3 where product_id=current_setting('bonus.product')::uuid and market='PH';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.user'),'role','authenticated','aal','aal1')::text,true);
 begin perform public.quote_fulfilment_checkout('PH',current_setting('bonus.items')::jsonb,null,'{"method":"delivery"}');raise exception 'FAIL: combined purchased/bonus quantity cap';exception when invalid_parameter_value then null;end;
 update public.product_offers set max_quantity=24 where product_id=current_setting('bonus.product')::uuid and market='PH';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.admin'),'role','authenticated','aal','aal2')::text,true);
 perform public.withdraw_bonus_campaign(c,'ROLLBACK-COMBINED');
 c:=public.approve_bonus_campaign('PH',d||'{"allowVoucher":true}'::jsonb,'ROLLBACK-COMBINATION');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.user'),'role','authenticated','aal','aal1')::text,true);
 q:=public.quote_fulfilment_checkout('PH',current_setting('bonus.items')::jsonb,'QA-BONUS-COMBINATION','{"method":"delivery"}');
 if q->>'subtotalMinor'<>'200'or q->>'discountMinor'<>'5'or q->>'totalMinor'<>'195'or q->'bonusItems'->0->>'quantity'<>'2'then raise exception 'FAIL: bonus altered voucher accounting';end if;
end $$;
do $$declare o uuid:=current_setting('bonus.paid_order')::uuid;r jsonb;begin
 if(select reserved from public.inventory where product_id=current_setting('bonus.gift')::uuid and market='PH')<>2 then raise exception 'FAIL: gift stock reservation';end if;
 if(select count(*)from public.order_items where order_id=o)<>1 or(select sum(net_minor)from public.order_items where order_id=o)<>200 then raise exception 'FAIL: gifts changed paid billing lines';end if;
 begin update public.orders set bonus_items='[]'where id=o;raise exception 'FAIL: mutable bonus snapshot';exception when raise_exception then if SQLERRM<>'Order bonus snapshot is immutable'then raise;end if;end;
 perform set_config('request.jwt.claims','{}',true);
 r:=public.prepare_stripe_checkout(o,current_setting('bonus.user')::uuid,false,'https://example.invalid');
 perform public.apply_stripe_checkout_event('evt_bonus_'||o,(r->>'id')::uuid,o,'cs_test_bonus_'||replace(o::text,'-',''),false,200,'php','complete','paid','pi_bonus'||replace(o::text,'-',''));
 if(select on_hand from public.inventory where product_id=current_setting('bonus.gift')::uuid and market='PH')<>98 or(select reserved from public.inventory where product_id=current_setting('bonus.gift')::uuid and market='PH')<>0 then raise exception 'FAIL: bonus payment stock transition';end if;
 if(select state from private.bonus_redemptions where order_id=o)<>'consumed'then raise exception 'FAIL: paid capacity not consumed';end if;
 if(select context->'bonusItems'->0->>'quantity'from private.notification_jobs where reference=o and kind='order_confirmed')<>'2'then raise exception 'FAIL: confirmation omitted bonus';end if;
 if private.compensation_payload(o,'order_paid')->'bonusItems'->0->>'quantity'<>'2'then raise exception 'FAIL: compensation facts omitted bonus';end if;
 if has_table_privilege('authenticated','private.bonus_campaigns','insert,update,delete,select')or has_table_privilege('authenticated','private.bonus_redemptions','select')then raise exception 'FAIL: direct bonus state privileges';end if;
end $$;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.user'),'role','authenticated','aal','aal1')::text,true);
do $$declare result jsonb;begin
 result:=public.export_my_data();
 if not exists(select 1 from jsonb_array_elements(result->'orders')o where o->>'id'=current_setting('bonus.paid_order')and o->'bonusItems'->0->>'quantity'='2')then raise exception 'FAIL: own export omitted bonus snapshot';end if;
end $$;
reset role;
do $$declare q jsonb;o uuid;begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.other'),'role','authenticated','aal','aal1')::text,true);
 q:=public.quote_fulfilment_checkout('PH',current_setting('bonus.items')::jsonb,null,'{"method":"delivery"}');
 o:=public.create_fulfilment_order('PH',current_setting('bonus.items')::jsonb,current_setting('bonus.address')::jsonb,gen_random_uuid(),current_setting('bonus.terms'),null,q->>'quoteHash',null,'{"method":"delivery"}');
 update public.inventory_reservations set expires_at=now()-interval '1 minute'where order_id=o;
 perform set_config('request.jwt.claims','{}',true);
 perform public.release_expired_reservations();
 if(select status from public.orders where id=o)<>'cancelled'or(select state from private.bonus_redemptions where order_id=o)<>'released'then raise exception 'FAIL: expiry did not release bonus allocation';end if;
 if exists(select 1 from public.inventory_reservations where order_id=o)then raise exception 'FAIL: expired gift reservation retained';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('bonus.other'),'role','authenticated','aal','aal1')::text,true);
 q:=public.quote_fulfilment_checkout('PH',current_setting('bonus.items')::jsonb,null,'{"method":"delivery"}');
 if q->'bonusItems'->0->>'quantity'<>'2'then raise exception 'FAIL: expiry capacity not reusable';end if;
end $$;
rollback;
